// ==================== GROUPS ====================
export const getGroups = async (filters: {
  is_public?: boolean;
  status?: string;
  admin_email?: string;
} = {}): Promise<Group[]> => {
  try {
    // Public browsing → SECURITY DEFINER RPC that exposes only non-sensitive columns.
    if (filters.is_public === true && !filters.admin_email) {
      const { data, error } = await (supabase as any).rpc('get_public_groups');
      if (error) throw error;
      return (data as Group[]) || [];
    }

    // Owner/member browsing → base table (RLS scopes to owner/member).
    let query = supabase.from('groups').select('*');
    if (filters.is_public !== undefined) query = query.eq('is_public', filters.is_public);
    if (filters.status) query = query.eq('status', filters.status);
    // NB: admin_email is column-revoked. Owner is already restricted by RLS,
    // so we simply return what the caller can see and let the caller filter.

    const { data, error } = await query.order('created_date', { ascending: false });
    if (error) throw error;

    let rows = (data as Group[]) || [];
    if (filters.admin_email) {
      const target = filters.admin_email.toLowerCase();
      // admin_email is not selectable; fall back to owner_id match via current session.
      const { data: sess } = await supabase.auth.getSession();
      const uid = sess.session?.user?.id;
      const email = sess.session?.user?.email?.toLowerCase();
      if (email === target && uid) {
        rows = rows.filter(g => g.owner_id === uid);
      } else {
        rows = [];
      }
    }
    return rows;
  } catch (error) {
    console.error('❌ getGroups error:', error);
    return [];
  }
};

export const getGroupById = async (id: string): Promise<Group | null> => {
  try {
    // Try full row first (owner / admin / member with RLS access).
    const full = await supabase.from('groups').select('*').eq('id', id).maybeSingle();
    if (full.data) return full.data as Group;
    // Fallback: safe RPC for non-members of public groups.
    const { data } = await (supabase as any).rpc('get_public_group', { _id: id });
    const row = Array.isArray(data) ? data[0] : data;
    return (row as Group) || null;
  } catch (error) {
    console.error('❌ getGroupById error:', error);
    return null;
  }
};


export const getGroupByInviteCode = async (inviteCode: string): Promise<Group | null> => {
  try {
    const { data, error } = await supabase.rpc('get_group_by_invite_code', {
      _code: inviteCode.toUpperCase(),
    });
    if (error) {
      console.error('❌ Error fetching group by invite code:', error);
      throw error;
    }
    const row = Array.isArray(data) ? data[0] : data;
    return (row as Group) || null;
  } catch (error) {
    console.error('❌ getGroupByInviteCode error:', error);
    return null;
  }
};

export const createGroup = async (groupData: Omit<Group, 'id'>): Promise<Group> => {
  const { data: sessionData, error: sessionError } = await supabase.auth.getSession();
  const session = sessionData.session;

  if (sessionError || !session?.user?.id || !session.user.email) {
    console.error('❌ Missing Supabase auth session while creating group:', sessionError);
    throw new Error('Devi effettuare di nuovo l’accesso prima di creare un gruppo.');
  }

  const authenticatedGroupData = {
    ...groupData,
    owner_id: session.user.id,
    admin_email: session.user.email.toLowerCase(),
  };

  const { data, error } = await supabase
    .from('groups')
    .insert([authenticatedGroupData] as any)
    .select()
    .single();
  
  if (error) {
    console.error('❌ Error creating group:', error);
    throw error;
  }
  
  return data;
};

export const updateGroup = async (id: string, updates: Partial<Group>): Promise<Group> => {
  const { data, error } = await supabase
    .from('groups')
    .update(updates as any)
    .eq('id', id)
    .select()
    .single();
  
  if (error) {
    console.error('❌ Error updating group:', error);
    throw error;
  }
  
  return data;
};

export const deleteGroup = async (id: string): Promise<void> => {
  const { error } = await supabase
    .from('groups')
    .delete()
    .eq('id', id);
  
  if (error) {
    console.error('❌ Error deleting group:', error);
    throw error;
  }
};

// ==================== MEMBERSHIPS ====================
export const getMemberships = async (filters: {
  group_id?: string;
  user_email?: string;
} = {}): Promise<Membership[]> => {
  try {
    // Listing members of a specific group → SECURITY DEFINER RPC that
    // strips Stripe IDs and other sensitive co-member fields.
    if (filters.group_id && !filters.user_email) {
      const { data, error } = await (supabase as any).rpc('get_group_members', {
        _group_id: filters.group_id,
      });
      if (error) throw error;
      return (data as Membership[]) || [];
    }

    // NB: `select('*')` fails with "permission denied" because Stripe columns are
    // column-revoked for `authenticated`. Select only the readable columns.
    const MEMBERSHIP_COLUMNS = [
      'id', 'group_id', 'user_email', 'user_name', 'user_avatar_url', 'role',
      'payment_status', 'cost_per_month', 'joined_date', 'created_date',
      'current_period_end', 'dunning_attempts', 'slot_type', 'duration_hours',
      'access_expires_at', 'auto_renew', 'cred_status', 'cred_status_at',
      'cred_issue_note', 'removal_requested_at', 'removal_effective_at',
      'removal_requested_by',
    ].join(', ');

    let query = supabase.from('memberships').select(MEMBERSHIP_COLUMNS);
    if (filters.group_id) query = query.eq('group_id', filters.group_id);
    if (filters.user_email) query = query.eq('user_email', filters.user_email);

    const { data, error } = await query.order('joined_date', { ascending: false });
    if (error) throw error;
    return (data || []) as unknown as Membership[];
  } catch (error) {
    console.error('❌ getMemberships error:', error);
    return [];
  }
};

export const getMembershipsByGroupId = async (groupId: string): Promise<Membership[]> => {
  return getMemberships({ group_id: groupId });
};

export const getUserMemberships = async (userEmail: string): Promise<Membership[]> => {
  return getMemberships({ user_email: userEmail });
};


