// ==================== TRUST SCORES ====================
export const getTrustScore = async (userEmail: string): Promise<TrustScore | null> => {
  try {
    const { data, error } = await supabase
      .from('trust_scores')
      .select('*')
      .eq('user_email', userEmail)
      .maybeSingle();
    
    if (error) {
      console.error('❌ Error fetching trust score:', error);
      return null;
    }
    
    return data as any;
  } catch (error) {
    console.error('❌ getTrustScore error:', error);
    return null;
  }
};

export const createOrUpdateTrustScore = async (
  userEmail: string, 
  updates: Partial<Omit<TrustScore, 'id' | 'user_email'>>
): Promise<TrustScore> => {
  const { data, error } = await supabase
    .from('trust_scores')
    .upsert([{ 
      user_email: userEmail, 
      ...updates,
      last_updated: new Date().toISOString()
    }] as any, { onConflict: 'user_email' })
    .select()
    .single() as any;
  
  if (error) {
    console.error('❌ Error upserting trust score:', error);
    throw error;
  }
  
  return data;
};

// ==================== REAL-TIME SUBSCRIPTIONS ====================
export const subscribeToGroupChanges = (
  groupId: string, 
  callback: (payload: any) => void
): (() => void) => {
  const channel = supabase
    .channel(`group-${groupId}`)
    .on(
      'postgres_changes',
      { 
        event: '*', 
        schema: 'public', 
        table: 'groups', 
        filter: `id=eq.${groupId}` 
      },
      (payload) => callback(payload)
    )
    .subscribe();
  
  return () => {
    supabase.removeChannel(channel);
  };
};

export const subscribeToMembershipChanges = (
  groupId: string, 
  callback: (payload: any) => void
): (() => void) => {
  const channel = supabase
    .channel(`memberships-${groupId}`)
    .on(
      'postgres_changes',
      { 
        event: '*', 
        schema: 'public', 
        table: 'memberships', 
        filter: `group_id=eq.${groupId}` 
      },
      (payload) => callback(payload)
    )
    .subscribe();
  
  return () => {
    supabase.removeChannel(channel);
  };
};

// ==================== HELPER FUNCTIONS ====================
export const generateInviteCode = (): string => {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  let code = "";
  for (let i = 0; i < 6; i++) {
    code += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return code;
};

export const checkIfUserIsMember = async (groupId: string, userEmail: string): Promise<boolean> => {
  const memberships = await getMemberships({ group_id: groupId, user_email: userEmail });
  return memberships.length > 0;
};

export const getGroupMemberCount = async (groupId: string): Promise<number> => {
  const memberships = await getMemberships({ group_id: groupId });
  return memberships.length;
};
